#include "exotic/cognition/reconsideration.hpp"
#include <cassert>
int main(){using namespace exotic::cognition;ReconsiderationEngine e;Intention current{"i1","Continue reliability investigation","c1","committed",0.8,"chosen earlier"};Intention alt{"i2","Investigate alternate root cause","c2","tentative",0.6,"new option"};auto low=e.consider(current,{0.1,0.1,0.1,0.1,0.8,0.0},alt);assert(!low.review_worthwhile);bool has_stay=false,has_none=false;for(const auto&o:low.options){if(o.action==ReconsiderationAction::StayCourse)has_stay=true;if(o.action==ReconsiderationAction::DoNothing)has_none=true;}assert(has_stay&&has_none);auto high=e.consider(current,{0.9,0.8,0.7,0.9,0.2,0.2},alt);assert(high.review_worthwhile);bool has_switch=false,has_suspend=false,has_abandon=false;for(const auto&o:high.options){assert(o.support>=0&&o.support<=1);if(o.action==ReconsiderationAction::Switch)has_switch=true;if(o.action==ReconsiderationAction::Suspend)has_suspend=true;if(o.action==ReconsiderationAction::Abandon)has_abandon=true;}assert(has_switch&&has_suspend&&has_abandon);auto stale=e.consider(current,{0,0,0,0,0.7,0.9});assert(stale.review_worthwhile);bool has_resume=false;for(const auto&o:stale.options)if(o.action==ReconsiderationAction::Resume)has_resume=true;assert(has_resume);assert(current.state=="committed");return 0;}
